-- TABLE INITIALIZATION BEGIN

-- Create organization table
CREATE TABLE organization
(
    organization_id       VARCHAR(255) PRIMARY KEY,
    name                  VARCHAR(255),
    address               VARCHAR(255),
    organization_admin_id VARCHAR(255)
);

-- Create personnel table
CREATE TABLE personnel
(
    person_id       VARCHAR(255) PRIMARY KEY,
    organization_id VARCHAR(255) REFERENCES organization (organization_id) ON DELETE CASCADE,
    first_name      VARCHAR(255),
    last_name       VARCHAR(255),
    email           VARCHAR(255)
);

-- Create software_agent table
CREATE TABLE software_agent
(
    software_agent_id  VARCHAR(255) PRIMARY KEY,
    name               VARCHAR(255),
    version            VARCHAR(255),
    description        TEXT,
    keycloak_client_id VARCHAR(255) UNIQUE
);

-- Create study table
CREATE TABLE study
(
    study_id    VARCHAR(255) PRIMARY KEY,
    name        VARCHAR(255),
    description TEXT,
    objectives  TEXT,
    ethics      TEXT,
    owner       VARCHAR(255) REFERENCES personnel (person_id)
);

-- Create population table
CREATE TABLE population
(
    population_id   VARCHAR(255) PRIMARY KEY,
    study_id        VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    population_url  VARCHAR(2048),
    version         VARCHAR(255),
    description     TEXT,
    characteristics TEXT,
    -- a definition version is registered once: (url, version) is its canonical identity
    UNIQUE (population_url, version)
);

-- Create experiment table
CREATE TABLE experiment
(
    experiment_id     VARCHAR(255) PRIMARY KEY,
    study_id          VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    research_question TEXT
);

-- Create survey table
CREATE TABLE survey
(
    survey_id VARCHAR(255) PRIMARY KEY,
    study_id  VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    question  TEXT,
    answer    TEXT,
    category  VARCHAR(255)
);

-- Create study_personnel table
CREATE TABLE study_personnel
(
    study_id     VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    personnel_id VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    role         VARCHAR(255) NOT NULL,
    PRIMARY KEY (study_id, personnel_id)
);

-- Create study_organization table
CREATE TABLE study_organization
(
    study_id                 VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    organization_id          VARCHAR(255) REFERENCES organization (organization_id) ON DELETE CASCADE,
    role                     VARCHAR(255),
    responsible_personnel_id VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    population_id            VARCHAR(255) REFERENCES population (population_id) ON DELETE CASCADE,
    PRIMARY KEY (study_id, organization_id)
);

-- Create featureset table
CREATE TABLE featureset
(
    featureset_id   VARCHAR(255) PRIMARY KEY,
    experiment_id   VARCHAR(255) REFERENCES experiment (experiment_id) ON DELETE CASCADE,
    title           VARCHAR(255),
    featureset_url  VARCHAR(2048),
    version         VARCHAR(255),
    description     TEXT,
    created_at      TIMESTAMP,
    created_by      VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    last_updated_at TIMESTAMP,
    last_updated_by VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    -- a definition version is registered once: (url, version) is its canonical identity
    UNIQUE (featureset_url, version)
);

-- Create feature table
CREATE TABLE feature
(
    feature_id      VARCHAR(255) PRIMARY KEY,
    featureset_id   VARCHAR(255) REFERENCES featureset (featureset_id) ON DELETE CASCADE,
    title           VARCHAR(255),
    description     TEXT,
    data_type       VARCHAR(255),
    is_outcome      BOOLEAN,
    mandatory       BOOLEAN,
    is_unique       BOOLEAN,
    units           VARCHAR(255),
    equipment       VARCHAR(255),
    data_collection VARCHAR(255),
    concept_uri     VARCHAR(255),
    concept_system  VARCHAR(255),
    concept_code    VARCHAR(255),
    -- how Studyfyr derived the final column, carried over from the dataset descriptor
    extraction_definition     TEXT,
    extraction_definition_url VARCHAR(2048),
    created_at      TIMESTAMP,
    created_by      VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    last_updated_at TIMESTAMP,
    last_updated_by VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE
);

-- Create quality_criteria table
CREATE TABLE quality_criteria
(
    quality_criteria_id VARCHAR(255) PRIMARY KEY,
    experiment_id       VARCHAR(255) REFERENCES experiment (experiment_id) ON DELETE CASCADE,
    title               VARCHAR(255),
    url                 VARCHAR(2048),
    description         TEXT,
    version             VARCHAR(255),
    created_at          TIMESTAMP,
    created_by          VARCHAR(255),
    last_updated_at     TIMESTAMP,
    last_updated_by     VARCHAR(255),
    -- a definition version is registered once: (url, version) is its canonical identity
    UNIQUE (url, version)
);

-- Create quality_criterion table
CREATE TABLE quality_criterion
(
    quality_criterion_id VARCHAR(255) PRIMARY KEY,
    quality_criteria_id  VARCHAR(255) REFERENCES quality_criteria (quality_criteria_id) ON DELETE CASCADE,
    feature_id           VARCHAR(255) REFERENCES feature (feature_id) ON DELETE CASCADE,
    name                 VARCHAR(255),
    description          TEXT,
    category             VARCHAR(255),
    context              VARCHAR(255),
    subcategory          VARCHAR(255),
    -- the expression language of "expression"
    language             VARCHAR(255) DEFAULT 'application/sql',
    -- the SQL over the virtual "dataset" table, computing aliased scalar measures
    expression           TEXT,
    -- the formula over those aliases, whose result is checked against low/high
    rule_expression      TEXT,
    low                  NUMERIC,
    high                 NUMERIC,
    created_at           TIMESTAMP,
    created_by           VARCHAR(255),
    last_updated_at      TIMESTAMP,
    last_updated_by      VARCHAR(255)
);

-- Create dataset table
CREATE TABLE dataset
(
    dataset_id       VARCHAR(255) PRIMARY KEY,
    featureset_id    VARCHAR(255) REFERENCES featureset (featureset_id) ON DELETE CASCADE,
    population_id    VARCHAR(255) REFERENCES population (population_id) ON DELETE CASCADE,
    organization_id  VARCHAR(255) REFERENCES organization (organization_id) ON DELETE CASCADE,
    title            VARCHAR(255),
    description      TEXT,
    version          VARCHAR(50),
    reference_entity VARCHAR(255),
    number_of_records   INTEGER,
    synthetic        BOOLEAN,
    -- a refresh is a new row in the chain, not an update of the old one
    previous_dataset_id    VARCHAR(255) REFERENCES dataset (dataset_id) ON DELETE SET NULL,
    -- HealthDCAT-AP: auto-derived and auto-computed content metadata
    persistent_identifier  VARCHAR(255),
    structured_data        BOOLEAN,
    temporal_coverage_start DATE,
    temporal_coverage_end  DATE,
    temporal_resolution    VARCHAR(255),
    geographical_coverage  VARCHAR(255),
    number_of_unique_individuals INTEGER,
    min_typical_age        INTEGER,
    max_typical_age        INTEGER,
    conforms_to            VARCHAR(255),
    provenance_statement   TEXT,
    was_generated_by       VARCHAR(255),
    created_at       TIMESTAMP,
    created_by       VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    last_updated_at  TIMESTAMP,
    last_updated_by  VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE
);

-- Create dataset_concept table
CREATE TABLE dataset_concept
(
    concept_id     VARCHAR(255) PRIMARY KEY,
    dataset_id     VARCHAR(255) REFERENCES dataset (dataset_id) ON DELETE CASCADE,
    -- the HealthDCAT-AP property this value fills, e.g. the health category
    property_uri   VARCHAR(255),
    concept_uri    VARCHAR(255),
    pref_label     VARCHAR(255),
    concept_scheme VARCHAR(255)
);

-- Create catalogue_dataset table
CREATE TABLE catalogue_dataset
(
    catalogue_dataset_id           VARCHAR(255) PRIMARY KEY,
    dataset_id                     VARCHAR(255) REFERENCES dataset (dataset_id) ON DELETE CASCADE,
    public_title                   VARCHAR(255),
    public_description             TEXT,
    access_rights                  VARCHAR(255),
    hdab_name                      VARCHAR(255),
    hdab_uri                       VARCHAR(2048),
    publisher_name                 VARCHAR(255),
    publisher_type                 VARCHAR(255),
    contact_point                  VARCHAR(255),
    legal_basis                    VARCHAR(255),
    purpose                        TEXT,
    personal_data                  BOOLEAN,
    publication_approval_reference VARCHAR(255),
    applicable_legislation         VARCHAR(255),
    retention_period_start         DATE,
    retention_period_end           DATE,
    landing_page                   VARCHAR(2048),
    documentation                  VARCHAR(2048),
    quality_annotation             VARCHAR(2048),
    created_at                     TIMESTAMP,
    created_by                     VARCHAR(255),
    last_updated_at                TIMESTAMP,
    last_updated_by                VARCHAR(255),
    -- one publication decision per dataset version
    UNIQUE (dataset_id)
);

-- Create dataset_distribution table
CREATE TABLE dataset_distribution
(
    distribution_id      VARCHAR(255) PRIMARY KEY,
    catalogue_dataset_id VARCHAR(255) REFERENCES catalogue_dataset (catalogue_dataset_id) ON DELETE CASCADE,
    title                VARCHAR(255),
    description          TEXT,
    access_url           VARCHAR(2048),
    download_url         VARCHAR(2048),
    access_service_uri   VARCHAR(2048),
    format               VARCHAR(255),
    media_type           VARCHAR(255),
    availability         VARCHAR(255),
    status               VARCHAR(255),
    licence              VARCHAR(255),
    rights               TEXT,
    byte_size            BIGINT,
    checksum_algorithm   VARCHAR(255),
    checksum_value       VARCHAR(255),
    created_at           TIMESTAMP,
    created_by           VARCHAR(255),
    last_updated_at      TIMESTAMP,
    last_updated_by      VARCHAR(255)
);

-- Create catalogue_registration table
CREATE TABLE catalogue_registration
(
    registration_id      VARCHAR(255) PRIMARY KEY,
    catalogue_dataset_id VARCHAR(255) REFERENCES catalogue_dataset (catalogue_dataset_id) ON DELETE CASCADE,
    -- which catalogue the record was published to, e.g. the organization's FDP
    catalogue_type       VARCHAR(255),
    catalogue_uri        VARCHAR(2048),
    listing_date         TIMESTAMP,
    -- created or updated: a refresh updates the existing entry in place
    change_type          VARCHAR(255),
    created_at           TIMESTAMP,
    created_by           VARCHAR(255),
    last_updated_at      TIMESTAMP,
    last_updated_by      VARCHAR(255)
);

-- Create quality_assessment table
CREATE TABLE quality_assessment
(
    quality_assessment_id VARCHAR(255) PRIMARY KEY,
    dataset_id            VARCHAR(255) REFERENCES dataset (dataset_id) ON DELETE CASCADE,
    quality_criteria_id   VARCHAR(255) REFERENCES quality_criteria (quality_criteria_id) ON DELETE CASCADE,
    overall_result        VARCHAR(255),
    summary               TEXT,
    executed_at           TIMESTAMP,
    -- personnel or software agent, so no FK is emitted here
    executed_by           VARCHAR(255)
);

-- Create quality_criterion_assessment_result table
CREATE TABLE quality_criterion_assessment_result
(
    result_id             VARCHAR(255) PRIMARY KEY,
    quality_assessment_id VARCHAR(255) REFERENCES quality_assessment (quality_assessment_id) ON DELETE CASCADE,
    quality_criterion_id  VARCHAR(255) REFERENCES quality_criterion (quality_criterion_id) ON DELETE CASCADE,
    value                 NUMERIC,
    result                VARCHAR(255),
    detail                TEXT
);

-- Create dataset_transformation table
CREATE TABLE dataset_transformation
(
    dataset_transformation_id VARCHAR(255) PRIMARY KEY,
    study_id               VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    title                  VARCHAR(255),
    description            TEXT
);

-- Create dataset_transformation_step table
CREATE TABLE dataset_transformation_step
(
    step_id                VARCHAR(255) PRIMARY KEY,
    dataset_transformation_id VARCHAR(255) REFERENCES dataset_transformation (dataset_transformation_id) ON DELETE CASCADE,
    step_order             INTEGER,
    -- the assessment whose findings motivated this step, when there is one
    quality_assessment_id  VARCHAR(255) REFERENCES quality_assessment (quality_assessment_id) ON DELETE SET NULL,
    input_features         VARCHAR(255),
    output_features        VARCHAR(255),
    method                 VARCHAR(255),
    explanation            TEXT,
    created_at             TIMESTAMP,
    created_by             VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    last_updated_at        TIMESTAMP,
    last_updated_by        VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE
);

-- Create learning_dataset table
CREATE TABLE learning_dataset
(
    learning_dataset_id    VARCHAR(255) PRIMARY KEY,
    dataset_id             VARCHAR(255) REFERENCES dataset (dataset_id) ON DELETE CASCADE,
    study_id               VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    dataset_transformation_id VARCHAR(255) REFERENCES dataset_transformation (dataset_transformation_id) ON DELETE CASCADE,
    description            TEXT
);

-- Create feature_dataset_characteristic table
CREATE TABLE feature_dataset_characteristic
(
    dataset_id          VARCHAR(255) REFERENCES dataset (dataset_id) ON DELETE CASCADE,
    feature_id          VARCHAR(255) REFERENCES feature (feature_id) ON DELETE CASCADE,
    characteristic_name VARCHAR(255),
    value               VARCHAR(255),
    value_data_type     VARCHAR(255),
    PRIMARY KEY (dataset_id, feature_id, characteristic_name)
);

-- Create parameter table
CREATE TABLE parameter
(
    parameter_id VARCHAR(255) PRIMARY KEY,
    name         VARCHAR(255),
    study_id     VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    description  TEXT,
    data_type    VARCHAR(255)
);

-- Create algorithm table
CREATE TABLE algorithm
(
    algorithm_id       VARCHAR(255) PRIMARY KEY,
    name               VARCHAR(255),
    objective_function TEXT,
    type               VARCHAR(255),
    sub_type           VARCHAR(255)
);

-- Create implementation table
CREATE TABLE implementation
(
    implementation_id VARCHAR(255) PRIMARY KEY,
    algorithm_id      VARCHAR(255) REFERENCES algorithm (algorithm_id) ON DELETE CASCADE,
    software          TEXT,
    name              VARCHAR(255),
    description       TEXT
);

-- Create learning_process table
CREATE TABLE learning_process
(
    learning_process_id VARCHAR(255) PRIMARY KEY,
    study_id            VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    implementation_id   VARCHAR(255) REFERENCES implementation (implementation_id) ON DELETE CASCADE,
    description         TEXT
);

-- Create learning_stage table
CREATE TABLE learning_stage
(
    learning_stage_id   VARCHAR(255) PRIMARY KEY,
    learning_process_id VARCHAR(255) REFERENCES learning_process (learning_process_id) ON DELETE CASCADE,
    learning_stage_name VARCHAR(255),
    description         TEXT,
    dataset_percentage  INTEGER
);

-- Create learning_process_dataset table
CREATE TABLE learning_process_dataset
(
    learning_process_id VARCHAR(255) REFERENCES learning_process (learning_process_id) ON DELETE CASCADE,
    learning_dataset_id VARCHAR(255) REFERENCES learning_dataset (learning_dataset_id) ON DELETE CASCADE,
    description         TEXT,
    PRIMARY KEY (learning_process_id, learning_dataset_id)
);

-- Create learning_process_parameter table
CREATE TABLE learning_process_parameter
(
    learning_process_id VARCHAR(255) REFERENCES learning_process (learning_process_id) ON DELETE CASCADE,
    parameter_id        VARCHAR(255) REFERENCES parameter (parameter_id) ON DELETE CASCADE,
    type                VARCHAR(255),
    value               TEXT,
    PRIMARY KEY (learning_process_id, parameter_id)
);

-- Create learning_stage_parameter table
CREATE TABLE learning_stage_parameter
(
    learning_stage_id VARCHAR(255) REFERENCES learning_stage (learning_stage_id) ON DELETE CASCADE,
    parameter_id      VARCHAR(255) REFERENCES parameter (parameter_id) ON DELETE CASCADE,
    type              VARCHAR(255),
    value             TEXT,
    PRIMARY KEY (learning_stage_id, parameter_id)
);

-- Create model table
CREATE TABLE model
(
    model_id               VARCHAR(255) PRIMARY KEY,
    learning_process_id    VARCHAR(255) REFERENCES learning_process (learning_process_id) ON DELETE CASCADE,
    study_id               VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    experiment_id          VARCHAR(255) REFERENCES experiment (experiment_id) ON DELETE CASCADE,
    name                   VARCHAR(255),
    version                VARCHAR(255),
    previous_model_id      VARCHAR(255) REFERENCES model (model_id) ON DELETE SET NULL,
    retraining_reason      TEXT,
    tag                    VARCHAR(255),
    model_type             VARCHAR(255),
    product_identifier     VARCHAR(255),
    owner_organization_id  VARCHAR(255) REFERENCES organization (organization_id) ON DELETE CASCADE,
    trl_level              VARCHAR(255),
    license                TEXT,
    primary_use            TEXT,
    secondary_use          TEXT,
    intended_users         TEXT,
    counter_indications    TEXT,
    ethical_considerations TEXT,
    limitations            TEXT,
    fairness_constraints   TEXT,
    created_at             TIMESTAMP,
    created_by             VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    last_updated_at        TIMESTAMP,
    last_updated_by        VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE
);

-- Create model_parameter table
CREATE TABLE model_parameter
(
    model_id     VARCHAR(255) REFERENCES model (model_id) ON DELETE CASCADE,
    parameter_id VARCHAR(255) REFERENCES parameter (parameter_id) ON DELETE CASCADE,
    type         VARCHAR(255),
    value        TEXT,
    PRIMARY KEY (model_id, parameter_id)
);

-- Create model_figure table
CREATE TABLE model_figure
(
    figure_id    VARCHAR(255) PRIMARY KEY,
    model_id     VARCHAR(255) REFERENCES model (model_id) ON DELETE CASCADE,
    title        VARCHAR(255),
    description  TEXT,
    image_base64 TEXT
);

-- Create linked_article table
CREATE TABLE linked_article
(
    article_id        VARCHAR(255) PRIMARY KEY,
    model_id          VARCHAR(255) REFERENCES model (model_id) ON DELETE CASCADE,
    doi               VARCHAR(255),
    title             VARCHAR(255),
    authors           TEXT,
    publication_venue VARCHAR(255),
    publication_year  INTEGER,
    url               VARCHAR(2048),
    description       TEXT
);

-- Create model_evaluation table
CREATE TABLE model_evaluation
(
    model_evaluation_id VARCHAR(255) PRIMARY KEY,
    model_id            VARCHAR(255) REFERENCES model (model_id) ON DELETE CASCADE,
    -- set only when the run is attributable to one site; training aggregates leave it null
    organization_id     VARCHAR(255) REFERENCES organization (organization_id) ON DELETE CASCADE,
    trigger             VARCHAR(255),
    aggregation_method  VARCHAR(255),
    executed_at         TIMESTAMP,
    executed_by         VARCHAR(255),
    description         TEXT
);

-- Create model_evaluation_dataset table
CREATE TABLE model_evaluation_dataset
(
    model_evaluation_id VARCHAR(255) REFERENCES model_evaluation (model_evaluation_id) ON DELETE CASCADE,
    learning_dataset_id VARCHAR(255) REFERENCES learning_dataset (learning_dataset_id) ON DELETE CASCADE,
    weight              NUMERIC,
    description         TEXT,
    PRIMARY KEY (model_evaluation_id, learning_dataset_id)
);

-- Create passport table
CREATE TABLE passport
(
    passport_id          VARCHAR(255) PRIMARY KEY,
    model_id             VARCHAR(255) REFERENCES model (model_id) ON DELETE CASCADE,
    study_id             VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    -- a passport is never rewritten: regenerating chains a new version onto the previous one
    version              INTEGER,
    previous_passport_id VARCHAR(255) REFERENCES passport (passport_id) ON DELETE SET NULL,
    created_at           TIMESTAMP,
    created_by           VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    approved_at          TIMESTAMP,
    approved_by          VARCHAR(255) REFERENCES personnel (person_id) ON DELETE CASCADE,
    details_json         JSONB,
    -- the document exactly as it was signed, plus its SHA-256 so a copy can be checked against the record
    signed_pdf           BYTEA,
    signed_pdf_hash      VARCHAR(64)
);

-- Create audit_log table
CREATE TABLE audit_log
(
    audit_log_id        VARCHAR(255) PRIMARY KEY,
    -- the actor is personnel or a software agent, so no FK is emitted here
    actor_id            VARCHAR(255),
    actor_name          VARCHAR(255),
    actor_type          VARCHAR(255) CHECK (actor_type IN ('PERSONNEL', 'SOFTWARE_AGENT')),
    study_id            VARCHAR(255) REFERENCES study (study_id) ON DELETE CASCADE,
    occurred_at         TIMESTAMP,
    action_type         VARCHAR(255),
    affected_relation   VARCHAR(255),
    affected_record_id  VARCHAR(255),
    affected_record     TEXT,
    description         TEXT
);

-- Create audit_log_book table
CREATE TABLE audit_log_book
(
    audit_log_id VARCHAR(255) REFERENCES audit_log (audit_log_id) ON DELETE CASCADE,
    passport_id  VARCHAR(255) REFERENCES passport (passport_id) ON DELETE CASCADE,
    PRIMARY KEY (audit_log_id, passport_id)
);

-- Create evaluation_measure table
CREATE TABLE evaluation_measure
(
    measure_id          VARCHAR(255) PRIMARY KEY,
    model_evaluation_id VARCHAR(255) REFERENCES model_evaluation (model_evaluation_id) ON DELETE CASCADE,
    name        VARCHAR(255),
    value       VARCHAR(255),
    data_type   VARCHAR(255),
    description TEXT
);

-- TABLE INITIALIZATIONS END - DATA INITIALIZATION BEGIN

