INSERT INTO population (population_id, study_id, population_url, version, description, characteristics)
VALUES
    ('0197a6f8-fbc4-7652-ae5d-d52eaa0a48db',
     '0197a6f8-2b78-71e4-81c1-b7b6a744ece3',
     'https://ai4hf.eu/cohorts/study1',
     '1.0',
     'Patients hospitalized with a primary discharge diagnosis of heart failure where the primary discharge diagnosis refers to the main reason for admission.',
     'The study population comprised 500 participants, evenly distributed between males and females, with seventy percent ranging between 20-30 years and the rest ranging between 40-50 years old.'),
    ('3197a6f8-2b78-71e4-81c1-b7b6a744ece5',
     '2197a6f8-2b78-71e4-81c1-b7b6a744ece4',
     'https://ai4hf.eu/cohorts/maggic/amsterdam-umc',
     '1.0',
     'Adults (18 years or older) with a recorded diagnosis of chronic heart failure, of any ejection fraction, who had at least one hospital or outpatient encounter at Amsterdam UMC from 2023-01-01. The reference point is the first qualifying encounter. Patients with congenital heart disease, or with less than one year of possible follow-up, are excluded.',
     '612 patients in the current extraction (dataset v1.1, January 2023 to March 2026); the original v1.0 extraction (to September 2025) held 500 of them. Mean age 71.3 years (SD 10.8, range 45-92), 39% women, mean LVEF 38.6%, 1-year all-cause mortality 21.4% (v1.0 figures).'),
    ('population_maggic_umcu',
     '2197a6f8-2b78-71e4-81c1-b7b6a744ece4',
     'https://ai4hf.eu/cohorts/maggic/umcu',
     '1.0',
     'Adults (18 years or older) with a recorded diagnosis of chronic heart failure, of any ejection fraction, who had at least one hospital or outpatient encounter at UMCU from 2023-03-01. The reference point is the first qualifying encounter. Patients with congenital heart disease, or with less than one year of possible follow-up, are excluded.',
     '412 patients (dataset v1.0, March 2023 to September 2025). Mean age 68.9 years (SD 11.4, range 41-89), 42% women, mean LVEF 37.2% (missing for 21.1% of patients), 1-year all-cause mortality 23.8%.');

