    created_at, created_by, approved_at, approved_by, details_json
)
VALUES
    ('passport_maggic_v1', 'b197a718-9800-7558-8565-5f760c97c8f9', '2197a6f8-2b78-71e4-81c1-b7b6a744ece4', 1, NULL,
     '2025-10-15 16:00:00', 'quality_assurance_specialist', '2025-10-16 09:00:00', 'quality_assurance_specialist',
     '{"surveys": [{"answer": "No. Each site trains locally under the federated protocol; only model updates and aggregate evaluation statistics leave the site.", "studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "category": "Data Governance", "question": "Is patient-level data shared outside the originating site?", "surveyId": "survey_maggic_data_access"}, {"answer": "Not yet. External validation against the original MAGGIC pooled-cohort risk score is planned once v1.0 is deployed.", "studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "category": "Validation", "question": "Has the MAGGIC-MLP model been externally validated?", "surveyId": "survey_maggic_external_validation"}, {"answer": "Planned. After deployment, the Monitoring Platform connector will import per-site statistics so drift can trigger retraining.", "studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "category": "Monitoring", "question": "Is the deployed model monitored for performance drift after release?", "surveyId": "survey_maggic_monitoring"}], "parameters": [{"name": "Hidden Layer Sizes", "studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "dataType": "string", "description": "Comma-separated neuron counts per hidden layer of the MLP, e.g. 64,32.", "parameterId": "param_maggic_hidden_layers"}, {"name": "Learning Rate", "studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "dataType": "decimal", "description": "Initial learning rate for the Adam optimizer.", "parameterId": "param_maggic_learning_rate"}, {"name": "Max Iterations", "studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "dataType": "int", "description": "Maximum training epochs before early stopping.", "parameterId": "param_maggic_max_iter"}, {"name": "L2 Regularization (alpha)", "studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "dataType": "decimal", "description": "L2 penalty term applied to the MLP weights.", "parameterId": "param_maggic_l2_alpha"}], "experiments": [{"studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "experimentId": "4197a6f8-2b78-71e4-81c1-b7b6a744ece5", "researchQuestion": "Can a MAGGIC-based model predict 1-year all cause mortality in Chronic Heart Failure?"}], "modelDetails": {"tag": "Production", "name": "MAGGIC-MLP Model (v1.0)", "license": "AI4HF-Research License v1.0", "modelId": "b197a718-9800-7558-8565-5f760c97c8f9", "studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "version": "1.0", "trlLevel": "TRL6", "createdAt": "2025-07-24T00:00:00Z", "createdBy": "data_scientist", "modelType": "Classification", "primaryUse": "Predicting 1-year mortality risk in chronic heart failure patients based on MAGGIC feature set.", "limitations": "Performance may degrade in cohorts with limited lab or echocardiographic data.", "experimentId": "4197a6f8-2b78-71e4-81c1-b7b6a744ece5", "secondaryUse": "Clinical risk stratification and care prioritization.", "intendedUsers": "Clinicians, cardiologists, and data science researchers.", "lastUpdatedAt": null, "lastUpdatedBy": null, "previousModelId": null, "retrainingReason": null, "learningProcessId": "b197a70f-a49d-71df-8f6d-d205da111e31", "productIdentifier": "AI4HF_MAGGIC_MLP_001", "counterIndications": "Not suitable for pediatric Chronic Heart Failure or congenital heart disease populations.", "fairnessConstraints": "Bias mitigation methods were applied across gender and age subgroups.", "ethicalConsiderations": "Ethically approved for retrospective analysis; patient identifiers are anonymized.", "ownerOrganizationName": "Amsterdam UMC"}, "modelFigures": [{"title": "ROC curve (v1.0, held-out test split)", "modelId": "b197a718-9800-7558-8565-5f760c97c8f9", "figureId": "figure_maggic_v1_auc", "description": "ROC curve of MAGGIC-MLP v1.0 on the held-out test split (n = 137, 31 deaths within 1 year): AUC 0.89; at the 0.5 threshold sensitivity is 83.9% and specificity 93.4%.", "imageBase64": ""}, {"title": "Confusion matrix (v1.0, held-out test split)", "modelId": "b197a718-9800-7558-8565-5f760c97c8f9", "figureId": "figure_maggic_v1_confusion", "description": "Confusion matrix of MAGGIC-MLP v1.0 on the held-out test split at the 0.5 threshold: 26 true positives, 5 false negatives, 7 false positives, 99 true negatives (accuracy 91.2%, precision 78.8%, F1 0.81).", "imageBase64": ""}], "studyDetails": {"id": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "name": "MAGGIC-MLP: Federated 1-Year Mortality Risk Prediction in Chronic Heart Failure", "owner": "study_owner", "ethics": "Approved on 2024-10-15 by the Medical Ethics Review Committee of Amsterdam UMC (application no. 234) as research not subject to the Dutch WMO, with local approval at UMCU. Individual informed consent was waived for this retrospective analysis of pseudonymised EHR data. Patient-level data does not leave the originating site.", "objectives": "1) Develop a calibrated multi-layer perceptron that predicts 1-year all-cause mortality from the MAGGIC predictors. 2) Compare its discrimination and calibration with the original MAGGIC integer risk score. 3) Report performance separately for each clinical partner, monitor it after deployment, and retrain when drift is detected.", "description": "Retrospective multi-centre study that develops MAGGIC-MLP, a neural network predicting 1-year all-cause mortality in adults with chronic heart failure from the 13 MAGGIC risk-score predictors. The model is trained with federated learning across two clinical partners in the Netherlands, Amsterdam UMC and UMCU (University Medical Center Utrecht): each site trains on its own EHR extraction, and only model updates and aggregate statistics leave the site. Version 1.0 was trained in October 2025 and is being prepared for deployment."}, "linkedArticles": [{"doi": "10.1093/eurheartj/ehs337", "url": "https://www.mdapp.co/heart-failure-life-expectancy-calculator-maggic-risk-score-484/", "title": "Predicting survival in heart failure: a risk score based on 39 372 patients from 30 studies", "authors": "Pocock SJ, Ariti CA, McMurray JJV, et al.", "modelId": "b197a718-9800-7558-8565-5f760c97c8f9", "articleId": "0197b0aa-1aaa-7b7b-bbbb-efefefefef01", "description": "The MAGGIC risk score this model is derived from.", "publicationYear": 2013, "publicationVenue": "European Heart Journal"}], "populationDetails": [{"studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "version": "1.0", "description": "Adults (18 years or older) with a recorded diagnosis of chronic heart failure, of any ejection fraction, who had at least one hospital or outpatient encounter at UMCU from 2023-03-01. The reference point is the first qualifying encounter. Patients with congenital heart disease, or with less than one year of possible follow-up, are excluded.", "populationId": "population_maggic_umcu", "populationUrl": "https://ai4hf.eu/cohorts/maggic/umcu", "characteristics": "412 patients (dataset v1.0, March 2023 to September 2025). Mean age 68.9 years (SD 11.4, range 41-89), 42% women, mean LVEF 37.2% (missing for 21.1% of patients), 1-year all-cause mortality 23.8%."}, {"studyId": "2197a6f8-2b78-71e4-81c1-b7b6a744ece4", "version": "1.0", "description": "Adults (18 years or older) with a recorded diagnosis of chronic heart failure, of any ejection fraction, who had at least one hospital or outpatient encounter at Amsterdam UMC from 2023-01-01. The reference point is the first qualifying encounter. Patients with congenital heart disease, or with less than one year of possible follow-up, are excluded.", "populationId": "3197a6f8-2b78-71e4-81c1-b7b6a744ece5", "populationUrl": "https://ai4hf.eu/cohorts/maggic/amsterdam-umc", "characteristics": "500 patients (dataset v1.0, January 2023 to September 2025). Mean age 71.3 years (SD 10.8, range 45-92), 39% women, mean LVEF 38.6%, 1-year all-cause mortality 21.4%."}], "featureSetsWithFeatures": [{"features": [{"title": "gender", "units": null, "dataType": "string", "isUnique": false, "createdAt": "2025-07-24T00:00:00Z", "createdBy": "data_engineer", "equipment": null, "featureId": "feat_gender", "isOutcome": false, "mandatory": true, "conceptUri": "http://snomed.info/id/263495000", "conceptCode": "263495000", "description": "Administrative gender of the patient (female or male).", "featuresetId": "6197a6f8-2b78-71e4-81c1-b7b6a744ece8", "conceptSystem": "http://snomed.info/sct", "lastUpdatedAt": "2025-07-24T00:00:00Z", "lastUpdatedBy": "data_engineer", "dataCollection": "EHR", "extractionDefinition": "Administrative gender taken from the patient demographics record.", "extractionDefinitionUrl": "https://ai4hf.eu/feature-sets/maggic-v1#gender"}, {"title": "age", "units": "years", "dataType": "integer", "isUnique": false, "createdAt": "2025-07-24T00:00:00Z", "createdBy": "data_engineer", "equipment": null, "featureId": "feat_age", "isOutcome": false, "mandatory": true, "conceptUri": "http://snomed.info/id/424144002", "conceptCode": "424144002", "description": "Age in years at the reference point.", "featuresetId": "6197a6f8-2b78-71e4-81c1-b7b6a744ece8", "conceptSystem": "http://snomed.info/sct", "lastUpdatedAt": "2025-07-24T00:00:00Z", "lastUpdatedBy": "data_engineer", "dataCollection": "EHR", "extractionDefinition": "Age in complete years computed as (reference point date - date of birth).", "extractionDefinitionUrl": "https://ai4hf.eu/feature-sets/maggic-v1#age"}, {"title": "nyha", "units": null, "dataType": "string", "isUnique": false, "createdAt": "2025-07-24T00:00:00Z", "createdBy": "data_engineer", "equipment": null, "featureId": "feat_nyha", "isOutcome": false, "mandatory": true, "conceptUri": "http://loinc.org/rid/88020-3", "conceptCode": "88020-3", "description": "Most recent New York Heart Association (NYHA) functional class, I to IV.", "featuresetId": "6197a6f8-2b78-71e4-81c1-b7b6a744ece8", "conceptSystem": "http://loinc.org", "lastUpdatedAt": "2025-07-24T00:00:00Z", "lastUpdatedBy": "data_engineer", "dataCollection": "EHR/Clinical assessment", "extractionDefinition": "Most recent NYHA functional class recorded before the reference point, taken from the structured clinical assessm